static uint8_t raw[COH_CLIENT_COSTUME_RAW_BYTES],packet[65536];static uint32_t indices[COH_CLIENT_COSTUME_INDEX_COUNT];static CohClientCostumeSlots slots;static CohOriginalCostumeWorkspace w;static CohOriginalCostumeSnapshot snapshot;static CohOriginalEntCostumeReport report;
