int main(int argc,char**argv){if(argc!=3)return 2;FILE*f=fopen(argv[1],"rb");if(!f||fread(raw,1,sizeof(raw),f)!=sizeof(raw)||fgetc(f)!=EOF)return 3;fclose(f);f=fopen(argv[2],"rb");uint8_t header[88],hash[32];if(!f||fread(header,1,88,f)!=88||memcmp(header,"COHIRP01",8)||le32(header+8)!=88||le32(header+12)>sizeof(packet))return 4;size_t bytes=le32(header+12);if(fread(packet,1,bytes,f)!=bytes||fgetc(f)!=EOF)return 5;fclose(f);SHA256(packet,bytes,hash);if(memcmp(hash,header+56,32))return 6;CohCostumeImportDigest d={digest,NULL,0,4096};if(coh_client_costume_slots_prepare((CohBytes){raw,sizeof(raw)},indices,COH_CLIENT_COSTUME_INDEX_COUNT,&d,&slots,8u<<20,sizeof(w)+sizeof(snapshot)+sizeof(report)+sizeof(packet)+COH_ORIGINAL_ENT_COSTUME_STACK_RESERVE)!=COH_OK)return 7;CohRepReader r={{packet,bytes},le64(header+16),le64(header+32),le32(header+40),COH_REP_BOUNDED_MESSAGE_MAX};CohStatus s=coh_original_ent_costume_receive_initial(&r,le32(header+48),le32(header+44),1,&slots,&w,&snapshot,&report);printf("{\"status\":%u,\"field\":%u,\"field_name\":\"%s\",\"end_bit\":%zu,\"packet_bits\":%zu,\"body_end\":%zu,\"appearance_end\":%zu,\"power_begin\":%zu,\"power_end\":%zu,\"power_entry_count\":%u,\"power_entries_read\":%u,\"power_unresolved_count\":%u,\"first_crc\":%u,\"last_crc\":%u,\"required_table\":%u,\"power_complete\":%u,\"titles_complete\":%u,\"ragdoll_complete\":%u,\"stats_complete\":%u,\"vision_complete\":%u,\"taskforce_complete\":%u,\"power_scratch\":%zu,\"bodyworkspace\":%zu,\"snapshot_bytes\":%zu,\"inventory_count\":%u,\"inventory_negative_words\":%u,\"inventory_begin\":%zu,\"inventory_end\":%zu}\n",s,report.field,coh_original_ent_costume_field_name(report.field),report.end_bit,report.packet_bits,report.selected_body_end_bit,report.appearance_end_bit,report.power_begin_bit,report.power_end_bit,report.power_entry_count,report.power_entries_read,report.power_unresolved_count,report.power_first_unresolved_crc,report.power_last_unresolved_crc,report.required_table,report.power_complete,report.titles_complete,report.ragdoll_complete,report.basic_stats_complete,report.vision_complete,report.taskforce_complete,report.power_scratch_bytes,sizeof(w),sizeof(snapshot),report.inventory_count,report.inventory_negative_words,report.inventory_begin_bit,report.inventory_end_bit);f=fopen("/tmp/coh-thor-016-costume-snapshot.bin","wb");if(!f||fwrite(&snapshot,1,sizeof(snapshot),f)!=sizeof(snapshot))return 8;fclose(f);return 0;}
